#!/usr/bin/env node
/**
 * Create test fixture repositories with seeded AI markers
 * Run with: node test/fixtures/create-fixtures.js
 */

const { execSync } = require('child_process');
const { writeFileSync, mkdirSync, rmSync, existsSync } = require('fs');
const { join } = require('path');

const FIXTURE_DIR = join(__dirname, 'repos');

function run(cmd, cwd) {
  try {
    execSync(cmd, { cwd, stdio: 'ignore' });
    return true;
  } catch (e) {
    console.error(`Command failed: ${cmd}`);
    console.error(e.message);
    return false;
  }
}

function write(file, content, cwd) {
  const fullPath = join(cwd, file);
  const dir = require('path').dirname(fullPath);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  writeFileSync(fullPath, content);
}

function initRepo(name) {
  const repoPath = join(FIXTURE_DIR, name);
  if (existsSync(repoPath)) rmSync(repoPath, { recursive: true, force: true });
  mkdirSync(repoPath, { recursive: true });
  run('git init', repoPath);
  run('git config user.name "Test User"', repoPath);
  run('git config user.email "test@example.com"', repoPath);
  return repoPath;
}

// Fixture 1: Repository with various AI markers
function createFixture1() {
  const repo = initRepo('fixture-ai-markers');
  
  // Initial commit
  write('README.md', '# Test Project\n\nA sample project with AI markers.', repo);
  run('git add README.md && git commit -m "Initial commit"', repo);

  // Commit with Co-Authored-By (bot email)
  write('src/main.js', '// Generated by GitHub Copilot\nfunction hello() { return "world"; }', repo);
  run('git add src/main.js && git commit -m "Add main.js\n\nCo-Authored-By: GitHub Copilot <41898282+github-copilot[bot]@users.noreply.github.com>"', repo);

  // Commit with Generated-By trailer
  write('src/utils.js', '// Created with Claude Code\nfunction util() { return 42; }', repo);
  run('git add src/utils.js && git commit -m "Add utils.js\n\nGenerated-By: claude-code"', repo);

  // Commit with AI-assisted message
  write('src/helper.py', '# Prompt: create a helper function\ndef helper():\n    return "helper"', repo);
  run('git add src/helper.py && git commit -m "Add helper.py - AI-assisted implementation"', repo);

  // Commit with Cursor signature
  write('src/component.tsx', '// Cursor: generated component\nexport function Component() { return <div>Hi</div>; }', repo);
  run('git add src/component.tsx && git commit -m "Add component.tsx\n\nCo-Authored-By: Cursor <cursor@users.noreply.github.com>"', repo);

  // Clean file (no markers)
  write('src/clean.js', 'function clean() { return "clean"; }', repo);
  run('git add src/clean.js && git commit -m "Add clean file"', repo);

  // File with inline AI comment
  write('src/inline.js', 'function foo() {\n  // AI: this was suggested by Copilot\n  return 1;\n}', repo);
  run('git add src/inline.js && git commit -m "Add inline.js"', repo);

  // File with header marker
  write('src/header.js', '/*\n * Generated by DeepSeek Coder\n * Date: 2024-01-15\n */\nexport function header() { return "header"; }', repo);
  run('git add src/header.js && git commit -m "Add header.js"', repo);

  // Commit with low-confidence keyword only
  write('src/low.js', '// This uses AI techniques\nfunction low() { return "low"; }', repo);
  run('git add src/low.js && git commit -m "Add low confidence file"', repo);

  console.log('Created fixture-ai-markers');
  return repo;
}

// Fixture 2: Clean repository (no AI markers)
function createFixture2() {
  const repo = initRepo('fixture-clean');
  
  write('README.md', '# Clean Project\n\nNo AI markers here.', repo);
  run('git add README.md && git commit -m "Initial commit"', repo);

  write('src/app.js', 'function app() { return "app"; }', repo);
  run('git add src/app.js && git commit -m "Add app"', repo);

  write('src/lib.js', 'export function lib() { return "lib"; }', repo);
  run('git add src/lib.js && git commit -m "Add lib"', repo);

  console.log('Created fixture-clean');
  return repo;
}

// Fixture 3: Mixed repository with some markers
function createFixture3() {
  const repo = initRepo('fixture-mixed');
  
  write('README.md', '# Mixed Project', repo);
  run('git add README.md && git commit -m "Init"', repo);

  // One AI commit
  write('ai-file.js', '// Generated by TabNine\nfunction ai() { return 1; }', repo);
  run('git add ai-file.js && git commit -m "Add AI file\n\nCo-Authored-By: TabNine <tabnine@users.noreply.github.com>"', repo);

  // Many clean commits
  for (let i = 1; i <= 5; i++) {
    write(`clean-${i}.js`, `function clean${i}() { return ${i}; }`, repo);
    run(`git add clean-${i}.js && git commit -m "Add clean ${i}"`, repo);
  }

  console.log('Created fixture-mixed');
  return repo;
}

// Main
function main() {
  console.log('Creating test fixtures...');
  if (existsSync(FIXTURE_DIR)) rmSync(FIXTURE_DIR, { recursive: true, force: true });
  mkdirSync(FIXTURE_DIR, { recursive: true });

  createFixture1();
  createFixture2();
  createFixture3();

  console.log('\nAll fixtures created in:', FIXTURE_DIR);
  console.log('Run tests with: npm test');
}

main();